export function renderTemplate(key: string, vars: Record<string, string | number> = {}): NotificationTemplate | null {
  const t = NOTIFICATION_TEMPLATES[key];
  if (!t) return null;
  const sub = (s: string) => s.replace(/\{(\w+)\}/g, (_m, k) => (vars[k] != null ? String(vars[k]) : ''));
  return {
    ...t,
    title: sub(t.title),
    titleBn: sub(t.titleBn),
    body: sub(t.body),
    bodyBn: sub(t.bodyBn),
    deeplink: t.deeplink.replace(/:(\w+)/g, (_m, k) => (vars[k] != null ? String(vars[k]) : ':' + k)),
  };
}
